def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    def move_towards(target_x, target_y):
        dx = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        dy = 0
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return dx, dy

    # Pursuit-evasion logic
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return list(move_towards(ox, oy))
        # Move to corners to catch evader
        corners = [
            [0, 0],
            [0, observation.get("grid_height",0) - 1],
            [observation.get("grid_width",0) - 1, 0],
            [observation.get("grid_width",0) - 1, observation.get("grid_height",0) - 1],
        ]
        opponent_pos = [ox, oy]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return list(move_towards(target[0], target[1]))

    # Territory control logic
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return list(move_towards(best[0], best[1]))

    # Resource collection logic
    resources = observation.get("resources") or []
    if resources:
        best = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return list(move_towards(best[0], best[1]))
    else:
        # No resources, move towards opponent as default
        return list(move_towards(ox, oy))

